resources.string:
uniform mat4 uMVPMatrix;
attribute vec3 vPosition;
attribute vec2 a_TexCoordinate;
varying vec2 texCoord;
varying vec2 posYZ;

void main() {

    gl_Position = uMVPMatrix * vec4(vPosition.xyz, 1.0);

    texCoord = a_TexCoordinate;
    posYZ = vPosition.yz;
}

precision mediump float;
uniform sampler2D u_Texture;
uniform float wave;
uniform float kind;
varying vec2 texCoord;
varying vec2 posYZ;

void main() {

vec2 texC = texCoord;

float waveFixed = wave;

texC.x = texC.x + kind * 0.212;
texC.x = texC.x + sin( waveFixed ) * 0.007 * posYZ.x;

vec4 color = texture2D(u_Texture, texC);

if(color.a<0.85){
    discard;
}

gl_FragColor = color;
}

precision mediump float;
uniform sampler2D u_Texture;
uniform sampler2D a_Texture;
uniform float wave;
varying vec2 texCoord;
varying vec2 posYZ;

void main() {

vec2 texC = texCoord;

vec4 colorA = texture2D(a_Texture, texC);

float waveFixedHard = wave + colorA.r * 0.4;


texC.x = texC.x + sin( waveFixedHard ) * 0.02 * colorA.r;

float waveFixed = wave * 2.0 + posYZ.y * 100.0;

texC.x = texC.x + sin( waveFixed ) * 0.002;
texC.y = texC.y + cos( waveFixed ) * 0.002;

vec4 color = texture2D(u_Texture, texC);

if(color.a<0.9){
    discard;
}

gl_FragColor = color;
}
